package com.yeyamo_mobile.api.feed_service.infrastructure.messaging;import static org.mockito.Mockito.*;import java.util.UUID;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.feed_service.application.FeedProjectionCommandService;
class FeedEventConsumerTests{@Test void contentEventReplayIsIgnored()throws Exception{UUID event=UUID.randomUUID(),post=UUID.randomUUID();FeedProjectionCommandService commands=mock(FeedProjectionCommandService.class);ProcessedEventRepository receipts=mock(ProcessedEventRepository.class);when(receipts.existsById(event)).thenReturn(false,true);FeedEventConsumer c=new FeedEventConsumer(new ObjectMapper(),commands,receipts);String json=("{\"eventId\":\"%s\",\"eventType\":\"content.post.published\",\"eventVersion\":1,\"producer\":\"content-service\",\"occurredAt\":\"2026-07-13T12:00:00Z\",\"payload\":{\"postId\":\"%s\",\"authorId\":\"a1\",\"status\":\"PUBLISHED\",\"visibility\":\"PUBLIC\",\"publishedAt\":\"2026-07-13T12:00:00Z\"}}").formatted(event,post);c.content(json);c.content(json);verify(commands,times(1)).content(eq("content.post.published"),any(),eq(event.toString()));verify(receipts,times(1)).save(any());}
 @Test void interactionEventReplayIsIgnored()throws Exception{UUID event=UUID.randomUUID(),post=UUID.randomUUID();FeedProjectionCommandService commands=mock(FeedProjectionCommandService.class);ProcessedEventRepository receipts=mock(ProcessedEventRepository.class);when(receipts.existsById(event)).thenReturn(false,true);FeedEventConsumer c=new FeedEventConsumer(new ObjectMapper(),commands,receipts);String json=("{\"eventId\":\"%s\",\"eventType\":\"interaction.like.added\",\"eventVersion\":1,\"producer\":\"interaction-service\",\"actorId\":\"u1\",\"payload\":{\"postId\":\"%s\",\"userId\":\"u1\"}}").formatted(event,post);c.interaction(json);c.interaction(json);verify(commands,times(1)).interaction("interaction.like.added",post,"u1",event.toString());}}
